with a as(select * from public.authors where open_library_id=any(array['OL40784A','OL24470A','OL841112A','OL12429055A','OL7679333A','OL96984A','OL15705810A','OL13097747A','OL6868201A','OL7468980A','OL28165A','OL1475013A']::text[]) or id=any(array[1549,227,1652,1595,1640,1579,368,1328]::bigint[])) select jsonb_build_object('checked_at',clock_timestamp(),'authors',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from a t),'author_corpora',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from public.works t where author_id in(select id from a)),'isbn_matches',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from public.editions t where regexp_replace(coalesce(isbn_13,''),'[-[:space:]]','','g')=any(array['9789022537312','9789029058759','9789023403555','9789402716290','9789049206154','9789049208899','9789029535878','9789021464206','9789022532607','9789022550946','9789083319650','9789022985823','9789029070850','9780002247191','9789022550939']::text[])),'source_work_matches',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from public.works t where open_library_id=any(array['OL554736W','OL4321136W','OL34337924W','OL39663865W','OL1019598W','OL23563282W','OL257938W','OL28018696W','OL41254W','OL257936W']::text[])),'title_matches',(select coalesce(jsonb_agg(jsonb_build_object('relation','works','row',to_jsonb(t))),'[]') from public.works t where regexp_replace(lower(normalize(title,NFD)),'[^a-z0-9]','','g')=any(array['servantoftheempire','dienaarvanhetkeizerrijk','thelittlefriend','dekleinevriend','thepumpkinspicecafe','hetpumpkinspicecafe','quicksilver','benimadmkrmz','ikheetkarmozijn','ithappenedonesummer','eenzomervolverrassingen','murderinlamut','dedriehuurlingen','childrenofmemory','kinderenvandeherinnering','lastmanstanding','delaatsteman','honouredenemy','deeervollevijand']::text[])),'edition_title_matches',(select coalesce(jsonb_agg(jsonb_build_object('relation','editions','row',to_jsonb(t))),'[]') from public.editions t where regexp_replace(lower(normalize(title,NFD)),'[^a-z0-9]','','g')=any(array['servantoftheempire','dienaarvanhetkeizerrijk','thelittlefriend','dekleinevriend','thepumpkinspicecafe','hetpumpkinspicecafe','quicksilver','benimadmkrmz','ikheetkarmozijn','ithappenedonesummer','eenzomervolverrassingen','murderinlamut','dedriehuurlingen','childrenofmemory','kinderenvandeherinnering','lastmanstanding','delaatsteman','honouredenemy','deeervollevijand']::text[])),'reserved_test_ranges',jsonb_build_object('works',(select count(*) from public.works where id between 987134001 and 987134999),'editions',(select count(*) from public.editions where id between 987234001 and 987234999),'authors',(select count(*) from public.authors where id between 987334001 and 987334999))) as preflight;
